export type OyService = 'oyster' | 'scallop' | 'urchin' | 'fish'
export interface OyVariant {
  name: string
  price: number
  unit?: string
}
export interface OyProduct {
  id: string
  name: string
  sec: string
  price: number | null
  old?: number
  unit: string
  img: string
  url: string
  labels: string[]
  order: boolean
  variants?: OyVariant[]
  def?: number
  service?: OyService
  live?: boolean
  gal: string[]
  desc: string[]
  props: [string, string][]
}
export interface OySection {
  id: string
  name: string
  icon: string
  count: number
  img: string
}
export interface OyReview {
  name: string
  text: string
}
export type OyTreeNode = string | { name: string; children?: OyTreeNode[] }

