// ---- helpers ----
export const oyMoney = (n: number) => `${Math.round(n).toLocaleString('ru-RU')} ₽`
export const oyPlural = (n: number, f: [string, string, string]) => {
  const a = Math.abs(n) % 100
  const b = a % 10
  if (a > 10 && a < 20) return f[2]
  if (b > 1 && b < 5) return f[1]
  if (b === 1) return f[0]
  return f[2]
}
export const oyUnitText = (u: string) => (u === 'набор' ? 'за набор' : `за ${u}`)
export const oyVariant = (p: OyProduct, i?: number) => (p.variants ? p.variants[i ?? p.def ?? 0] : null)
export const oyPrice = (p: OyProduct, i?: number) => oyVariant(p, i)?.price ?? p.price
export const oyUnit = (p: OyProduct, i?: number) => oyVariant(p, i)?.unit ?? p.unit
export const oyStep = (p: OyProduct, i?: number) => (oyUnit(p, i) === 'кг' && p.sec !== 'ryba' && p.sec !== 'krab' && p.sec !== 'premium' ? 0.5 : 1)
export const oyDiscount = (p: OyProduct) => (p.old && p.price ? Math.round((1 - p.price / p.old) * 100) : 0)
export const oyShort = (s: string, n = 64) => {
  if (s.length <= n) return s
  const cut = s.slice(0, n)
  return cut.slice(0, cut.lastIndexOf(' ')) + '…'
}
// Происхождение — первая строка свойств «Страна происхождения»
export const oyOrigin = (p: OyProduct) => p.props.find((x) => /страна/i.test(x[0]))?.[1] ?? ''
export const oySection = (id: string) => oySections.find((s) => s.id === id)
export const oyProduct = (id: string) => oyProducts.find((p) => p.id === id)
// Разделы пересекаются, как у оригинала: в «Морепродукты» входят краб, креветки, ежи и устрицы, в «Премиальные» — сеты и краб
const OY_INCLUDES: Record<string, string[]> = { more: ['krab', 'krevetki', 'ezhi', 'ustritsy'], premium: ['sety', 'krab', 'chernaya'] }
export const oyInSection = (p: OyProduct, id: string) => p.sec === id || (OY_INCLUDES[id] ?? []).includes(p.sec)
export const oyTreeName = (n: OyTreeNode) => (typeof n === 'string' ? n : n.name)
export const oySectionByName = (name: string) => {
  const k = name.toLowerCase().replace('ё', 'е')
  return oySections.find((s) => s.name.toLowerCase().replace('ё', 'е') === k)
}
// Подраздел меню → поиск по основе слова внутри раздела (выборка концепта, не весь каталог)
export const oyStem = (s: string) =>
  s
    .toLowerCase()
    .replace('ё', 'е')
    .split(/[\s(),]+/)
    .filter((w) => w.length > 2)
    .map((w) => w.slice(0, Math.max(4, w.length - 2)))
export const oyMatch = (p: OyProduct, q: string) => {
  const name = p.name.toLowerCase().replace('ё', 'е') + ' ' + p.props.map((x) => x[1]).join(' ').toLowerCase()
  return oyStem(q).every((w) => name.includes(w))
}
// Живое «когда привезём» по Москве: заказы 10–19, день в день 12–21
export const oyMoscowNow = () => {
  const d = new Date()
  const utc = d.getTime() + d.getTimezoneOffset() * 60000
  return new Date(utc + 3 * 3600000)
}
export const oyWhen = (now: Date) => {
  const h = now.getHours() + now.getMinutes() / 60
  const hm = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`
  if (h < 10) return { hm, today: true, short: 'Сегодня 12–21', text: 'Приём заказов с 10:00 — привезём сегодня с 12 до 21' }
  if (h < 19) {
    const left = 19 * 60 - (now.getHours() * 60 + now.getMinutes())
    const lh = Math.floor(left / 60)
    const lm = left % 60
    return { hm, today: true, short: 'Сегодня 12–21', text: `Закажите в течение ${lh ? `${lh} ч ` : ''}${lm} мин — привезём сегодня с 12 до 21` }
  }
  return { hm, today: false, short: 'Завтра 12–21', text: 'Заказы после 19:00 привезём завтра с 12 до 21 или к интервалу' }
}
